        { id: 'mod_19', subject: 'history', topic: 'Consolidation of British Power', question: 'The Dual System of Government in Bengal was established by:', options: ['Warren Hastings', 'Robert Clive', 'Lord Cornwallis', 'Lord Wellesley'], correct: 1, explanation: 'Robert Clive established the Dual System (1765-1772) where Diwani was with the Company and Nizamat with the Nawab.' },
        { id: 'mod_20', subject: 'history', topic: 'Consolidation of British Power', question: 'Tipu Sultan was defeated and killed in which Anglo-Mysore War?', options: ['First', 'Second', 'Third', 'Fourth'], correct: 3, explanation: 'Tipu Sultan died in the Fourth Anglo-Mysore War (1799) defending Srirangapatna against Lord Wellesley.' },
        { id: 'mod_21', subject: 'history', topic: 'Consolidation of British Power', question: 'Which battle decisively established British supremacy in Bengal?', options: ['Battle of Plassey', 'Battle of Buxar', 'Battle of Wandiwash', 'Battle of Panipat'], correct: 1, explanation: 'Battle of Buxar (1764) was decisive � British defeated combined forces of Mir Qasim, Shuja-ud-Daula and Shah Alam II.' },
        { id: 'mod_22', subject: 'history', topic: 'Socio-Religious Reform Movements', question: 'Who founded the Ramakrishna Mission?', options: ['Ramakrishna Paramahamsa', 'Swami Vivekananda', 'Raja Ram Mohan Roy', 'Ishwar Chandra Vidyasagar'], correct: 1, explanation: 'Swami Vivekananda founded the Ramakrishna Mission in 1897.' },
        { id: 'mod_23', subject: 'history', topic: 'Socio-Religious Reform Movements', question: 'The slogan "Go back to the Vedas" was given by:', options: ['Swami Vivekananda', 'Raja Ram Mohan Roy', 'Swami Dayanand Saraswati', 'Annie Besant'], correct: 2, explanation: 'Swami Dayanand Saraswati, founder of Arya Samaj (1875), gave the call "Go back to the Vedas".' },
        { id: 'mod_24', subject: 'history', topic: 'Socio-Religious Reform Movements', question: 'Who founded the Satyashodhak Samaj?', options: ['B.R. Ambedkar', 'Jyotirao Phule', 'E.V. Ramasamy Naicker', 'Sri Narayana Guru'], correct: 1, explanation: 'Jyotirao Phule founded the Satyashodhak Samaj in 1873 to fight caste discrimination.' },
        { id: 'mod_25', subject: 'history', topic: 'Land Revenue Systems & Pre-1857 Revolts', question: 'The Permanent Settlement of Bengal was introduced by:', options: ['Warren Hastings', 'Lord Cornwallis', 'Thomas Munro', 'Lord William Bentinck'], correct: 1, explanation: 'Lord Cornwallis introduced the Permanent Settlement in Bengal and Bihar in 1793.' },
        { id: 'mod_26', subject: 'history', topic: 'Land Revenue Systems & Pre-1857 Revolts', question: 'In which region was the Ryotwari System primarily implemented?', options: ['Bengal and Bihar', 'United Provinces', 'Madras and Bombay Presidencies', 'Punjab'], correct: 2, explanation: 'The Ryotwari System was introduced by Thomas Munro and Alexander Read in Madras and Bombay Presidencies.' },
        { id: 'mod_27', subject: 'history', topic: 'Land Revenue Systems & Pre-1857 Revolts', question: 'The Santhal Rebellion (1855-56) was led by:', options: ['Birsa Munda', 'Sidhu and Kanhu', 'Titu Mir', 'Alluri Sitarama Raju'], correct: 1, explanation: 'Brothers Sidhu and Kanhu Murmu led the Santhal Rebellion against the oppressive zamindari system.' },
        { id: 'mod_28', subject: 'history', topic: 'The Revolt of 1857', question: 'The Revolt of 1857 started on May 10 from which city?', options: ['Delhi', 'Jhansi', 'Meerut', 'Lucknow'], correct: 2, explanation: 'The Indian Rebellion of 1857 began as a mutiny of sepoys on 10 May 1857 in the cantonment of Meerut.' },
        { id: 'mod_29', subject: 'history', topic: 'The Revolt of 1857', question: 'Who called the 1857 Revolt the "First War of Indian Independence"?', options: ['R.C. Majumdar', 'V.D. Savarkar', 'S.N. Sen', 'Jawaharlal Nehru'], correct: 1, explanation: 'V.D. Savarkar described the revolt as a national war of independence in his book.' },
        { id: 'mod_30', subject: 'history', topic: 'The Revolt of 1857', question: 'Who led the 1857 revolt in Kanpur?', options: ['Begum Hazrat Mahal', 'Nana Saheb', 'Kunwar Singh', 'Rani Lakshmibai'], correct: 1, explanation: 'Nana Saheb, the adopted son of Peshwa Baji Rao II, led the mutiny in Kanpur with general Tatya Tope.' },
        { id: 'mod_31', subject: 'history', topic: 'Indian National Congress & Early Nationalism', question: 'Who was the first President of the Indian National Congress?', options: ['A.O. Hume', 'Dadabhai Naoroji', 'W.C. Bonnerjee', 'Badruddin Tyabji'], correct: 2, explanation: 'W.C. Bonnerjee presided over the first session of the INC held at Bombay in 1885.' },
        { id: 'mod_32', subject: 'history', topic: 'Indian National Congress & Early Nationalism', question: 'Who formulated the "Drain of Wealth" theory?', options: ['G.K. Gokhale', 'Dadabhai Naoroji', 'M.G. Ranade', 'R.C. Dutt'], correct: 1, explanation: 'Dadabhai Naoroji formulated the Drain of Wealth theory in his book "Poverty and Un-British Rule in India".' },
        { id: 'mod_33', subject: 'history', topic: 'Indian National Congress & Early Nationalism', question: 'Who was the first Muslim President of the INC?', options: ['Abul Kalam Azad', 'Badruddin Tyabji', 'Rafi Ahmed Kidwai', 'M.A. Ansari'], correct: 1, explanation: 'Badruddin Tyabji became the first Muslim President of the INC at the Madras session in 1887.' },
        { id: 'mod_34', subject: 'history', topic: 'Bengal Partition, Swadeshi & Revolutionary Movement', question: 'The Partition of Bengal (1905) was carried out by:', options: ['Lord Minto', 'Lord Curzon', 'Lord Hardinge', 'Lord Chelmsford'], correct: 1, explanation: 'Lord Curzon partitioned Bengal on 16 October 1905.' },
        { id: 'mod_35', subject: 'history', topic: 'Bengal Partition, Swadeshi & Revolutionary Movement', question: 'In which session did the INC split into Extremists and Moderates?', options: ['Calcutta Session (1906)', 'Surat Session (1907)', 'Lahore Session (1909)', 'Lucknow Session (1916)'], correct: 1, explanation: 'The INC split at the Surat session in 1907.' },
        { id: 'mod_36', subject: 'history', topic: 'Bengal Partition, Swadeshi & Revolutionary Movement', question: 'When was the Partition of Bengal annulled?', options: ['1909', '1911', '1915', '1919'], correct: 1, explanation: 'The Partition of Bengal was annulled in 1911 by Lord Hardinge at the Delhi Durbar.' },
        { id: 'mod_37', subject: 'history', topic: 'The Gandhian Era (1915-1925)', question: "Gandhi's first major Satyagraha in India was at:", options: ['Kheda', 'Ahmedabad', 'Champaran', 'Bardoli'], correct: 2, explanation: "Gandhi's first Satyagraha in India was in Champaran (Bihar) in 1917 against the Tinkathia system." },
        { id: 'mod_38', subject: 'history', topic: 'The Gandhian Era (1915-1925)', question: 'The Jallianwala Bagh massacre took place on:', options: ['13 April 1919', '18 March 1919', '15 August 1919', '23 March 1920'], correct: 0, explanation: 'The massacre took place in Amritsar on 13 April 1919 under orders of General Dyer.' },
        { id: 'mod_39', subject: 'history', topic: 'The Gandhian Era (1915-1925)', question: 'Who founded the Swaraj Party in 1923?', options: ['Gandhi and Nehru', 'C.R. Das and Motilal Nehru', 'Bose and Patel', 'Tilak and Besant'], correct: 1, explanation: 'Chittaranjan Das and Motilal Nehru formed the Swaraj Party on January 1, 1923.' },
        { id: 'mod_40', subject: 'history', topic: 'Revolutionary Nationalism (Phase II) & Simon Commission', question: 'Who was martyred after a lathi charge while protesting against the Simon Commission?', options: ['Bhagat Singh', 'Chandra Shekhar Azad', 'Lala Lajpat Rai', 'B.K. Dutt'], correct: 2, explanation: 'Lala Lajpat Rai died in November 1928 due to head injuries from a police lathi charge.' },
        { id: 'mod_41', subject: 'history', topic: 'Revolutionary Nationalism (Phase II) & Simon Commission', question: 'Who threw a bomb in the Central Legislative Assembly in 1929?', options: ['Bhagat Singh and Rajguru', 'Bhagat Singh and Batukeshwar Dutt', 'Azad and Sukhdev', 'Bismil and Ashfaqulla Khan'], correct: 1, explanation: 'Bhagat Singh and Batukeshwar Dutt threw a bomb in the Central Legislative Assembly on April 8, 1929.' },
        { id: 'mod_42', subject: 'history', topic: 'Civil Disobedience Movement & Round Table Conferences', question: 'In which session was the "Purna Swaraj" resolution adopted?', options: ['Calcutta (1928)', 'Lahore (1929)', 'Karachi (1931)', 'Faizpur (1936)'], correct: 1, explanation: 'The Purna Swaraj resolution was adopted at the Lahore session in 1929 under Jawaharlal Nehru.' },
        { id: 'mod_43', subject: 'history', topic: 'Civil Disobedience Movement & Round Table Conferences', question: 'Mahatma Gandhi started the Dandi March on:', options: ['26 January 1930', '12 March 1930', '6 April 1930', '5 March 1931'], correct: 1, explanation: 'Gandhi began the Dandi March from Sabarmati Ashram on 12 March 1930.' },
        { id: 'mod_44', subject: 'history', topic: 'Civil Disobedience Movement & Round Table Conferences', question: 'Who attended all three Round Table Conferences?', options: ['Mahatma Gandhi', 'Jawaharlal Nehru', 'B.R. Ambedkar', 'Madan Mohan Malaviya'], correct: 2, explanation: 'Dr. B.R. Ambedkar attended all three Round Table Conferences (1930-1932).' },
        { id: 'mod_45', subject: 'history', topic: 'Civil Disobedience Movement & Round Table Conferences', question: 'The Poona Pact (1932) was an agreement between:', options: ['Gandhi and Lord Irwin', 'Gandhi and Ramsay MacDonald', 'Gandhi and B.R. Ambedkar', 'Gandhi and Jinnah'], correct: 2, explanation: 'The Poona Pact (1932) between Gandhi and B.R. Ambedkar provided reserved seats for depressed classes.' },
        { id: 'mod_46', subject: 'history', topic: 'Towards Independence (1935-1947)', question: 'Which Act introduced provincial autonomy in British India?', options: ['Indian Councils Act 1909', 'Government of India Act 1919', 'Government of India Act 1935', 'Indian Independence Act 1947'], correct: 2, explanation: 'The Government of India Act 1935 introduced Provincial Autonomy by abolishing dyarchy in provinces.' },
        { id: 'mod_47', subject: 'history', topic: 'Towards Independence (1935-1947)', question: 'Who founded the Forward Bloc in 1939?', options: ['Jawaharlal Nehru', 'Subhas Chandra Bose', 'Sardar Patel', 'C. Rajagopalachari'], correct: 1, explanation: 'Subhas Chandra Bose formed the Forward Bloc in 1939 after resigning from the INC presidency.' },
        { id: 'mod_48', subject: 'history', topic: 'Towards Independence (1935-1947)', question: 'Who gave the "Do or Die" slogan?', options: ['Jawaharlal Nehru', 'Subhas Chandra Bose', 'Mahatma Gandhi', 'Sardar Patel'], correct: 2, explanation: 'Gandhi gave the "Do or Die" slogan during the Quit India Movement in August 1942.' },
        { id: 'mod_49', subject: 'history', topic: 'Governor-Generals & Viceroys of India', question: 'Who abolished the Sati System in 1829?', options: ['Lord Dalhousie', 'Lord Cornwallis', 'Lord William Bentinck', 'Lord Hastings'], correct: 2, explanation: 'Lord William Bentinck, with the help of Raja Ram Mohan Roy, outlawed Sati in 1829.' },
        { id: 'mod_50', subject: 'history', topic: 'Governor-Generals & Viceroys of India', question: 'Who is known as the "Father of Local Self Government" in India?', options: ['Lord Ripon', 'Lord Lytton', 'Lord Curzon', 'Lord Mayo'], correct: 0, explanation: 'Lord Ripon is called the Father of Local Self Government for his 1882 resolution.' },
        { id: 'mod_51', subject: 'history', topic: 'Governor-Generals & Viceroys of India', question: 'The Vernacular Press Act (1878) was enacted by:', options: ['Lord Dufferin', 'Lord Lytton', 'Lord Ripon', 'Lord Northbrook'], correct: 1, explanation: 'Lord Lytton enacted the Vernacular Press Act in 1878 to suppress criticism in Indian language press.' },
        { id: 'mod_52', subject: 'history', topic: 'Governor-Generals & Viceroys of India', question: 'Who was the last Governor-General of independent India?', options: ['Lord Mountbatten', 'C. Rajagopalachari', 'Dr. Rajendra Prasad', 'Jawaharlal Nehru'], correct: 1, explanation: 'C. Rajagopalachari was the first Indian and last Governor-General of independent India.' }
